// =====================================================================
//  BANGIRAS FIXES: one-click INSTALLER (Script macro, run as GM)
//  Select Bangiras's token, then run. Safe to re-run: replaces what it wrote.
//  Installs (as CPR Embedded Macros):
//   - Magicians Judge: Stasis v2 (advantage vs Topple and other prone saves)
//   - Magicians Judge: Sand Shroud animation (plays while the effect lasts)
//   - Metamagic: Quickened Spell (spell list, Bonus Action used, Action given back)
//   - Sorcery Incarnate (second Metamagic while Innate Sorcery is active)
//     + updates Heightened and Twinned so they can be the second option
//   - Sorcerous Restoration (asks after a Short Rest)
//   - Mantle of Flame (starts/ends with Innate Sorcery) and Phoenix Spark (burst whenever used)
//   - Hold Monster / Hold Person end-of-turn Wisdom saves
//  And checks Fire Shield's CPR automation.
// =====================================================================
const SCRIPTS = {
 "holdDc": "// =====================================================================\n//  HOLD PERSON / HOLD MONSTER: live save DC (Chris's Premades Embedded Macro)\n//  On the Hold spell.  Type: Midi Item | Pass: rollFinished | Priority: 60\n//  (fix-hold-spells.js and the Bangiras installer write this for you)\n//\n//  After each cast, the end-of-turn save on every held target is set to the\n//  DC this cast actually used, so bonuses active at casting time (Innate\n//  Sorcery's +1, items, etc.) carry into the repeat saves.\n// =====================================================================\n\nconst dc = Number(workflow.saveDC) || Number(workflow.activity?.save?.dc?.value)\n    || Number(workflow.actor.system.attributes?.spell?.dc);\nif (!dc) return;\nconst spellUuid = workflow.item.uuid;\nawait genericUtils.sleep(500);                       // let Midi finish applying the effects\nfor (const token of workflow.targets ?? []) {\n    const target = token.actor;\n    if (!target) continue;\n    for (const effect of target.effects.filter(e => e.origin === spellUuid || e.origin?.startsWith(spellUuid + '.'))) {\n        const changes = foundry.utils.deepClone(effect.changes ?? []);\n        let touched = false;\n        for (const c of changes) {\n            if (c.key !== 'flags.midi-qol.OverTime') continue;\n            c.value = String(c.value).replace(/saveDC\\s*=\\s*[^,]*/, 'saveDC=' + dc);\n            touched = true;\n        }\n        if (touched) await genericUtils.update(effect, {changes});\n    }\n}\n",
 "stasis": "// =====================================================================\n//  MAGICIANS JUDGE: STASIS (v2): Chris's Premades Embedded Macro\n//  On the Magicians Judge item.  Type: Save | Pass: situational | Priority: 50\n//  (the Bangiras fixes installer writes this for you)\n//\n//  Advantage on saving throws against anything that would knock him prone,\n//  including the Topple weapon mastery. v1 only looked at the source item,\n//  but Topple is a temporary item (\"Mastery: Topple\") that no longer exists\n//  by the time he saves, so v2 also reads the chat card that asked for it.\n// =====================================================================\n\nconst staff = trigger.entity;\nif (!staff.system.equipped || (staff.system.attunement && !staff.system.attuned)) return;\nconst PRONE = /\\bprone\\b|\\btopple/i;\nconst uuid = trigger.config?.midiOptions?.saveItemUuid;\nconst texts = [];\n\n// 1. The item that asked for the save, if it still exists.\nconst source = uuid ? fromUuidSync(uuid) : null;\nif (source) {\n    texts.push(source.name, String(source.system?.description?.value ?? ''));\n    for (const e of source.effects?.contents ?? []) {\n        if (e.statuses?.has?.('prone')) texts.push('prone');\n        for (const c of e.changes ?? []) texts.push(String(c.value));\n    }\n}\n// 2. The chat card for that item (works for temporary items like Mastery: Topple).\nconst recent = game.messages.contents.slice(-30).reverse();\nconst card = uuid ? recent.find(m => m.flags?.dnd5e?.item?.uuid === uuid || m.flags?.['midi-qol']?.itemUuid === uuid) : null;\nif (card) texts.push(card.flavor ?? '', card.content ?? '', card.flags?.dnd5e?.item?.data?.name ?? '');\n// 3. No item given: a Topple card in the last few seconds that names him.\nif (!uuid) {\n    const now = Date.now();\n    const m = recent.find(x => now - (x.timestamp ?? 0) < 15000 && /topple/i.test((x.flavor ?? '') + (x.content ?? '')));\n    if (m) texts.push(m.flavor ?? '', m.content ?? '');\n}\nif (texts.some(t => PRONE.test(t))) trigger.options.advantage = true;\n",
 "sandStart": "await (async () => {\n    const effect = trigger.entity;\n    const token = actorUtils.getFirstToken(effect.parent);\n    if (!token || !globalThis.Sequencer) return;\n    const pick = list => list.find(f => Sequencer.Database.entryExists(f));\n    const below = pick(['jb2a.shield_themed.below.molten_earth.03.orange', 'jb2a.shield_themed.below.molten_earth.01.orange']);\n    const above = pick(['jb2a.shield_themed.above.molten_earth.03.orange', 'jb2a.shield_themed.above.molten_earth.01.orange']);\n    const ring = pick(['jb2a.token_border.circle.spinning.orange.004', 'jb2a.token_border.circle.spinning.orange.001']);\n    const burst = pick(['jb2a.impact.ground_crack.orange.01', 'jb2a.impact.ground_crack.orange.02']);\n    const NAME = 'Sand Shroud ' + effect.parent.id;\n    const seq = new Sequence();\n    if (burst) seq.effect().file(burst).atLocation(token).belowTokens().scaleToObject(2.5);\n    if (below) seq.effect().file(below).attachTo(token).belowTokens().scaleToObject(1.8).opacity(0.9)\n        .fadeIn(400).fadeOut(400).persist().name(NAME);\n    if (above) seq.effect().file(above).attachTo(token).scaleToObject(1.8).opacity(0.6)\n        .fadeIn(800).fadeOut(400).persist().name(NAME);\n    if (ring) seq.effect().file(ring).attachTo(token).scaleToObject(2).opacity(0.7)\n        .fadeIn(400).fadeOut(400).persist().name(NAME);\n    await seq.play();\n})();",
 "sandEnd": "await (async () => {\n    const effect = trigger.entity;\n    const token = actorUtils.getFirstToken(effect.parent);\n    if (!globalThis.Sequencer) return;\n    await Sequencer.EffectManager.endEffects({name: 'Sand Shroud ' + effect.parent.id, ...(token ? {object: token} : {})});\n})();",
 "heightened": "// =====================================================================\n//  HEIGHTENED SPELL (2024): Chris's Premades Embedded Macro\n//  Put on: the \"Metamagic: Heightened Spell\" feature > CPR Medkit >\n//          Embedded Macros\n//  Type: Midi Item   |   Pass: rollFinished   |   Priority: 50\n//  (CPR's own automation on this feature must be set to None.)\n//\n//  1. He targets the creature(s), then clicks Heightened Spell. It spends 2\n//     Sorcery Points and lists his castable spells that force a saving throw.\n//  2. He picks one and it's cast straight away. Once targets are locked in,\n//     before anyone saves, he picks ANY one of the spell's targets: friend,\n//     foe, premade or custom token.\n//  3. That creature has disadvantage on its saves against that spell\n//     (including repeat saves) for up to 1 minute. It's removed as soon as the\n//     spell no longer affects that creature (it saved, the spell was one-off,\n//     or concentration ended).\n//  Cancelling the spell list refunds the Sorcery Points.\n// =====================================================================\n\nconst PRIMED_IDENTIFIER = 'heightenedSpellPrimed';\nconst TARGET_IDENTIFIER = 'heightenedSpellTarget';\nconst DURATION_SECONDS = 60;          // how long the disadvantage can last\n\nconst actor = workflow.actor;\nconst title = workflow.item.name;\n\n// Replace any older primed effect so a re-click doesn't stack.\nconst old = effectUtils.getEffectByIdentifier(actor, PRIMED_IDENTIFIER);\nif (old) await genericUtils.remove(old);\n\n// ---- Script carried by the primed effect: runs when the next spell is cast ----\n// Runs in CPR's Midi scope (trigger, workflow, CPR utils). trigger.entity = the primed effect.\nconst onCast = async () => {\n    if (workflow.item?.type !== 'spell') return;\n    const forcesSave = workflow.saveActivity || workflow.activity?.type === 'save' || workflow.activity?.save;\n    if (!forcesSave) return;                       // not a save spell: stay primed\n    const primed = trigger.entity;\n    const targets = Array.from(workflow.targets ?? []).filter(t => t.actor);\n    if (!targets.length) return;\n    const cfg = primed.flags.world?.heightened ?? {};\n    await genericUtils.remove(primed);\n\n    // Every target of the spell is offered: no friend/foe filter.\n    const chosen = targets.length === 1 ? [targets[0]]\n        : await dialogUtils.selectTargetDialog(primed.name,\n            'Which target has disadvantage on its saves against ' + workflow.item.name + '?',\n            targets, {skipDeadAndUnconscious: false, displayDistance: false});\n    const target = chosen?.[0];\n    if (!target?.actor) return;\n\n    // Scripts on the target's effect, run in CPR's save passes.\n    const situational = async () => {\n        const h = trigger.entity.flags.world?.heightenedTarget;\n        if (!h) return;\n        const fromItem = trigger.config?.midiOptions?.saveItemUuid;\n        // Match saves made against this spell; if Midi didn't say which item\n        // the save is for, fall back to the very first save after casting.\n        if (fromItem ? fromItem === h.spellUuid : h.firstSaveOpen) trigger.options.disadvantage = true;\n    };\n    // After a save against the spell: once the spell no longer affects the\n    // target (saved, or it was a one-off like Fireball), Heightened is used up.\n    const post = async () => {\n        const effect = trigger.entity;\n        const h = effect.flags.world?.heightenedTarget;\n        if (!h) return;\n        if (h.firstSaveOpen) await genericUtils.update(effect, {'flags.world.heightenedTarget.firstSaveOpen': false});\n        await genericUtils.sleep(1500);                       // let Midi apply or remove the spell's effects\n        const actor = effect.parent;\n        if (!actor?.effects.get(effect.id)) return;\n        const lingering = actor.effects.some(e => e.id !== effect.id\n            && (e.origin === h.spellUuid || String(e.origin ?? '').startsWith(h.spellUuid + '.')));\n        if (!lingering) await genericUtils.remove(effect);\n    };\n    // End of each of the target's turns: if the spell is gone (concentration\n    // dropped, dispelled...), remove Heightened too.\n    const turnEnd = async () => {\n        const effect = trigger.entity;\n        const h = effect.flags.world?.heightenedTarget;\n        if (!h || h.firstSaveOpen) return;\n        const actor = effect.parent;\n        const lingering = actor.effects.some(e => e.id !== effect.id\n            && (e.origin === h.spellUuid || String(e.origin ?? '').startsWith(h.spellUuid + '.')));\n        if (!lingering) await genericUtils.remove(effect);\n    };\n\n    await effectUtils.createEffect(target.actor, {\n        name: 'Heightened: ' + workflow.item.name,\n        img: primed.img,\n        origin: workflow.item.uuid,\n        duration: {seconds: cfg.duration ?? 60, rounds: Math.ceil((cfg.duration ?? 60) / 6)},\n        description: 'Disadvantage on saving throws against ' + workflow.item.name + '.',\n        flags: {\n            world: {heightenedTarget: {spellUuid: workflow.item.uuid, firstSaveOpen: true}},\n            'chris-premades': {embeddedMacros: [\n                {name: 'Heightened save', type: 'save', pass: 'situational', priority: 50,\n                    macro: 'await (' + situational.toString() + ')();'},\n                {name: 'Heightened save end', type: 'save', pass: 'post', priority: 50,\n                    macro: 'await (' + post.toString() + ')();'},\n                {name: 'Heightened turn check', type: 'combat', pass: 'turnEnd', priority: 50,\n                    macro: 'await (' + turnEnd.toString() + ')();'}\n            ]}\n        }\n    }, {identifier: cfg.targetIdentifier ?? 'heightenedSpellTarget'});\n\n    await ChatMessage.create({\n        speaker: ChatMessage.getSpeaker({actor: workflow.actor}),\n        content: '<b>Heightened Spell:</b> ' + target.document.name + ' has disadvantage on saves against '\n            + workflow.item.name + '.'\n    });\n};\n\nawait effectUtils.createEffect(actor, {\n    name: title,\n    img: workflow.item.img,\n    origin: workflow.item.uuid,\n    duration: {rounds: 1},\n    description: 'The next spell he casts that forces a saving throw is Heightened.',\n    flags: {\n        world: {heightened: {duration: DURATION_SECONDS, targetIdentifier: TARGET_IDENTIFIER}},\n        'chris-premades': {embeddedMacros: [\n            {name: 'Heightened cast', type: 'midi-actor', pass: 'preambleComplete', priority: 40,\n                macro: 'await (' + onCast.toString() + ')();'}\n        ]}\n    }\n}, {identifier: PRIMED_IDENTIFIER});\n\n// ---- Sorcery Incarnate: primed as a SECOND Metamagic -------------------------\n// The Sorcery Incarnate macro sets this flag when it adds this option to a spell\n// that another Metamagic option is already casting. Prime only, don't cast.\nif (actor.getFlag('world', 'nixMetamagicPrimeOnly')) {\n    await actor.unsetFlag('world', 'nixMetamagicPrimeOnly');\n    return;\n}\n\n// ---- Pick the spell, then cast it -------------------------------------------\n// Lists only spells he can cast right now (prepared, with a slot or use left).\nconst refundAndClear = async (why) => {\n    const primed = effectUtils.getEffectByIdentifier(actor, PRIMED_IDENTIFIER);\n    if (primed) await genericUtils.remove(primed);\n    const points = actor.items.find(i => i.type === 'feat' && ['sorcery points'].includes(i.name.toLowerCase().trim()));\n    const cost = Number(workflow.activity?.consumption?.targets?.[0]?.value ?? 0);\n    if (points && cost && (points.system.uses?.spent ?? 0) >= cost) {\n        await genericUtils.update(points, {'system.uses.spent': points.system.uses.spent - cost});\n    }\n    ui.notifications.info(title + ': ' + why + ' Sorcery Points refunded.');\n};\n// Spells he can cast right now: cantrips, at-will/innate spells, spells with\n// uses left, and leveled spells he has a slot for (that level or higher).\n// Slot level comes from the slot key itself (spell3 = 3rd), pact slots use their level.\nconst castableSpells = () => {\n    const slots = Object.entries(actor.system.spells ?? {})\n        .filter(([key, slot]) => (slot?.value ?? 0) > 0)\n        .map(([key, slot]) => key === 'pact' ? Number(slot.level ?? 0) : Number(key.replace('spell', '')))\n        .filter(n => n > 0);\n    const maxSlot = Math.max(0, ...slots);\n    const seen = new Set();\n    return actor.items.filter(s => {\n        if (s.type !== 'spell') return false;\n        const lvl = s.system.level ?? 0;\n        const method = s.system.method ?? s.system.preparation?.mode;\n        const ok = lvl === 0 || ['atwill', 'innate'].includes(method)\n            || (s.system.uses?.max && (s.system.uses.value ?? 0) > 0 && method !== 'spell')\n            || maxSlot >= lvl;\n        if (!ok) return false;\n        const key = s.name + '|' + lvl;           // hide duplicate copies (e.g. two Hex entries)\n        if (seen.has(key)) return false;\n        seen.add(key);\n        return true;\n    });\n};\nconst spells = castableSpells()\n    .filter(s => s.system.activities?.some(a => a.type === 'save') || s.hasSave)\n    .sort((a, b) => (a.system.level - b.system.level) || a.name.localeCompare(b.name));\nif (!spells.length) {\n    await refundAndClear('no castable spells force a saving throw.');\n    return;\n}\nconst spell = await dialogUtils.selectDocumentDialog(title, 'Heighten which spell? (Only spells that force a saving throw are listed.)', spells,\n    {showSpellLevel: true, addNoneDocument: true});\nif (!spell) {\n    await refundAndClear('no spell chosen.');\n    return;\n}\nconst spellActivity = (spell.system.activities.find(a => a.type === 'save') ?? spell.system.activities.contents[0]);\n// Cast it once this Metamagic use has finished. Target the creature(s) first as usual;\n// the normal casting window (slot level etc.) still appears.\nsetTimeout(() => spellActivity?.use(), 250);\n",
 "twinned": "// =====================================================================\n//  TWINNED SPELL (2024): Chris's Premades Embedded Macro\n//  Put on: the \"Metamagic: Twinned Spell\" feature > CPR Medkit >\n//          Embedded Macros\n//  Type: Midi Item   |   Pass: rollFinished   |   Priority: 50\n//  (CPR's own automation on this feature must be set to None.)\n//\n//  1. He targets BOTH creatures, then clicks Twinned Spell. It spends 1\n//     Sorcery Point and lists only spells that target an additional creature\n//     when cast at a higher level (Hold Monster, Charm Person, Banishment...).\n//  2. He picks one and it's cast straight away on both targets. If he had\n//     only one creature targeted, he's asked for the second before any save\n//     or attack. Cancelling refunds the Sorcery Point.\n//\n//  Normally one Metamagic option per spell. With Sorcery Incarnate (while\n//  Innate Sorcery is active) the Sorcery Incarnate macro can add a second.\n// =====================================================================\n\nconst PRIMED_IDENTIFIER = 'twinnedSpellPrimed';\nconst SORCERY_POINT_NAMES = ['sorcery points'];\nconst COST = 1;\n\nconst actor = workflow.actor;\nconst title = workflow.item.name;\n\nconst old = effectUtils.getEffectByIdentifier(actor, PRIMED_IDENTIFIER);\nif (old) await genericUtils.remove(old);\n\n// ---- Script carried by the primed effect: runs when the next spell is cast ----\n// Runs in CPR's Midi scope (trigger, workflow, CPR utils). trigger.entity = the primed effect.\nconst onCast = async () => {\n    if (workflow.item?.type !== 'spell') return;\n    const primed = trigger.entity;\n    const cfg = primed.flags.world?.twinned ?? {};\n    const caster = workflow.token;\n    const casterActor = workflow.actor;\n\n    const refund = async (why) => {\n        await genericUtils.remove(primed);\n        const points = casterActor.items.find(i => i.type === 'feat'\n            && (cfg.pointNames ?? ['sorcery points']).includes(i.name.toLowerCase().trim()));\n        if (points && (points.system.uses?.spent ?? 0) > 0) {\n            await genericUtils.update(points, {'system.uses.spent': Math.max(0, points.system.uses.spent - (cfg.cost ?? 1))});\n        }\n        ui.notifications.info('Twinned Spell: ' + why + ' Sorcery Point refunded.');\n    };\n\n    const activity = workflow.activity;\n    if (!caster) return refund('no token for the caster.');\n    await genericUtils.remove(primed);\n\n    // He targets both creatures before casting. Only if he targeted just one\n    // does he get asked for the second.\n    let targets = Array.from(workflow.targets ?? []).filter(t => t.actor);\n    if (targets.length < 2) {\n        const range = activity?.range ?? {};\n        const maxDistance = range.units === 'touch' ? 5 : (Number(range.value) > 0 ? Number(range.value) : Infinity);\n        const already = new Set(targets.map(t => t.document.uuid));\n        const candidates = canvas.tokens.placeables\n            .filter(t => t.actor && !already.has(t.document.uuid) && !t.document.hidden)\n            .filter(t => tokenUtils.getDistance(caster, t) <= maxDistance)\n            .sort((a, b) => tokenUtils.getDistance(caster, a) - tokenUtils.getDistance(caster, b));\n        if (!candidates.length) return refund('no second creature within range of ' + workflow.item.name + '.');\n        const chosen = await dialogUtils.selectTargetDialog('Twinned Spell',\n            'Only one creature was targeted. Choose the second target for ' + workflow.item.name + '.',\n            candidates, {skipDeadAndUnconscious: false, coverToken: caster, displayDistance: true});\n        const twin = chosen?.[0];\n        if (!twin) return refund('no second target chosen.');\n        workflow.targets.add(twin);\n        if (workflow.hitTargets && !activity?.attack) workflow.hitTargets.add(twin);\n        twin.setTarget(true, {releaseOthers: false, groupSelection: true});\n        targets.push(twin);\n    }\n    const twin = targets[targets.length - 1];\n\n    await ChatMessage.create({\n        speaker: ChatMessage.getSpeaker({actor: casterActor}),\n        content: '<b>Twinned Spell:</b> ' + workflow.item.name + ' is cast one level higher and targets <b>' + targets.map(t => t.document.name).join('</b> and <b>') + '</b>.'\n    });\n};\n\nawait effectUtils.createEffect(actor, {\n    name: title,\n    img: workflow.item.img,\n    origin: workflow.item.uuid,\n    duration: {rounds: 1},\n    description: 'The next spell he casts can target one additional creature.',\n    flags: {\n        world: {twinned: {cost: COST, pointNames: SORCERY_POINT_NAMES}},\n        'chris-premades': {embeddedMacros: [\n            {name: 'Twinned cast', type: 'midi-actor', pass: 'preambleComplete', priority: 30,\n                macro: 'await (' + onCast.toString() + ')();'}\n        ]}\n    }\n}, {identifier: PRIMED_IDENTIFIER});\n\n// ---- Sorcery Incarnate: primed as a SECOND Metamagic -------------------------\n// The Sorcery Incarnate macro sets this flag when it adds this option to a spell\n// that another Metamagic option is already casting. Prime only, don't cast.\nif (actor.getFlag('world', 'nixMetamagicPrimeOnly')) {\n    await actor.unsetFlag('world', 'nixMetamagicPrimeOnly');\n    return;\n}\n\n// ---- Pick the spell, then cast it -------------------------------------------\n// Lists only spells he can cast right now (prepared, with a slot or use left).\nconst refundAndClear = async (why) => {\n    const primed = effectUtils.getEffectByIdentifier(actor, PRIMED_IDENTIFIER);\n    if (primed) await genericUtils.remove(primed);\n    const points = actor.items.find(i => i.type === 'feat' && ['sorcery points'].includes(i.name.toLowerCase().trim()));\n    const cost = Number(workflow.activity?.consumption?.targets?.[0]?.value ?? 0);\n    if (points && cost && (points.system.uses?.spent ?? 0) >= cost) {\n        await genericUtils.update(points, {'system.uses.spent': points.system.uses.spent - cost});\n    }\n    ui.notifications.info(title + ': ' + why + ' Sorcery Points refunded.');\n};\n// Spells he can cast right now: cantrips, at-will/innate spells, spells with\n// uses left, and leveled spells he has a slot for (that level or higher).\n// Slot level comes from the slot key itself (spell3 = 3rd), pact slots use their level.\nconst castableSpells = () => {\n    const slots = Object.entries(actor.system.spells ?? {})\n        .filter(([key, slot]) => (slot?.value ?? 0) > 0)\n        .map(([key, slot]) => key === 'pact' ? Number(slot.level ?? 0) : Number(key.replace('spell', '')))\n        .filter(n => n > 0);\n    const maxSlot = Math.max(0, ...slots);\n    const seen = new Set();\n    return actor.items.filter(s => {\n        if (s.type !== 'spell') return false;\n        const lvl = s.system.level ?? 0;\n        const method = s.system.method ?? s.system.preparation?.mode;\n        const ok = lvl === 0 || ['atwill', 'innate'].includes(method)\n            || (s.system.uses?.max && (s.system.uses.value ?? 0) > 0 && method !== 'spell')\n            || maxSlot >= lvl;\n        if (!ok) return false;\n        const key = s.name + '|' + lvl;           // hide duplicate copies (e.g. two Hex entries)\n        if (seen.has(key)) return false;\n        seen.add(key);\n        return true;\n    });\n};\n// 2024 Twinned: only spells whose higher-level casting targets an additional creature.\nconst TWINNABLE = /(additional|extra|one more) (creature|target|humanoid|beast|willing creature)/i;\nconst twinnable = s => TWINNABLE.test(String(s.system.description?.value ?? '').replace(/<[^>]+>/g, ' '));\nconst spells = castableSpells()\n    .filter(s => s.system.level > 0 && twinnable(s))\n    .sort((a, b) => (a.system.level - b.system.level) || a.name.localeCompare(b.name));\nif (!spells.length) {\n    await refundAndClear('no castable spells can be twinned.');\n    return;\n}\nconst spell = await dialogUtils.selectDocumentDialog(title, 'Twin which spell? (Only spells that target an additional creature when upcast. Target both creatures before picking.)', spells,\n    {showSpellLevel: true, addNoneDocument: true});\nif (!spell) {\n    await refundAndClear('no spell chosen.');\n    return;\n}\nconst spellActivity = spell.system.activities.contents[0];\n// Cast it once this Metamagic use has finished. Target the creature(s) first as usual;\n// the normal casting window (slot level etc.) still appears.\nsetTimeout(() => spellActivity?.use(), 250);\n",
 "quickened": "// =====================================================================\n//  QUICKENED SPELL (2024): Chris's Premades Embedded Macro\n//  Put on: the \"Metamagic: Quickened Spell\" feature > CPR Medkit >\n//          Embedded Macros   (the installer does this for you)\n//  Type: Midi Item   |   Pass: rollFinished   |   Priority: 50\n//  (CPR's own automation on this feature must be set to None.)\n//\n//  1. He clicks Quickened Spell. It spends 2 Sorcery Points and lists his\n//     castable spells that take 1 action.\n//  2. He picks one and it's cast straight away (normal slot window).\n//  3. When the spell finishes, Midi's tracker shows his Bonus Action as used,\n//     and his Action is given back (if it wasn't already used before).\n//  Cancelling the list refunds the Sorcery Points.\n//  With Sorcery Incarnate, Quickened can also be the second Metamagic on a spell.\n// =====================================================================\n\nconst PRIMED_IDENTIFIER = 'quickenedSpellPrimed';\n\nconst actor = workflow.actor;\nconst title = workflow.item.name;\n\nconst old = effectUtils.getEffectByIdentifier(actor, PRIMED_IDENTIFIER);\nif (old) await genericUtils.remove(old);\n\n// ---- Script carried by the primed effect: runs when the spell finishes ----\n// Runs in CPR's Midi scope. trigger.entity = the primed effect.\nconst onDone = async () => {\n    if (workflow.item?.type !== 'spell') return;\n    if (workflow.activity?.activation?.type !== 'action') return;   // not a 1-action spell: stay primed\n    const primed = trigger.entity;\n    const q = primed.flags.world?.quickened ?? {};\n    const a = workflow.actor;\n    await genericUtils.remove(primed);\n    // Bonus Action used.\n    try {\n        if (globalThis.MidiQOL?.hasUsedBonusAction && !MidiQOL.hasUsedBonusAction(a)) await MidiQOL.setBonusActionUsed(a);\n    } catch (e) { console.warn('Quickened Spell: could not mark the bonus action', e); }\n    // Midi marks the Action as used for a 1-action spell; give it back.\n    const giveBack = async () => {\n        if (q.actionUsedBefore) return;\n        if (a.getFlag('midi-qol', 'actions')?.action) await MidiQOL.removeActionUsed(a);\n    };\n    await giveBack();\n    setTimeout(giveBack, 800);                      // in case Midi sets it a moment later\n    await ChatMessage.create({\n        speaker: ChatMessage.getSpeaker({actor: a}),\n        content: '<b>Quickened Spell:</b> ' + workflow.item.name + ' was cast as a Bonus Action.'\n    });\n};\n\nawait effectUtils.createEffect(actor, {\n    name: title,\n    img: workflow.item.img,\n    origin: workflow.item.uuid,\n    duration: {rounds: 1},\n    description: 'The next 1-action spell he casts takes a Bonus Action instead.',\n    flags: {\n        world: {quickened: {actionUsedBefore: !!actor.getFlag('midi-qol', 'actions')?.action}},\n        'chris-premades': {embeddedMacros: [\n            {name: 'Quickened done', type: 'midi-actor', pass: 'rollFinished', priority: 60,\n                macro: 'await (' + onDone.toString() + ')();'}\n        ]}\n    }\n}, {identifier: PRIMED_IDENTIFIER});\n\n// ---- Sorcery Incarnate: primed as a SECOND Metamagic: don't cast ------------\nif (actor.getFlag('world', 'nixMetamagicPrimeOnly')) {\n    await actor.unsetFlag('world', 'nixMetamagicPrimeOnly');\n    return;\n}\n\n// ---- Pick the spell, then cast it -------------------------------------------\nconst refundAndClear = async (why) => {\n    const primed = effectUtils.getEffectByIdentifier(actor, PRIMED_IDENTIFIER);\n    if (primed) await genericUtils.remove(primed);\n    const points = actor.items.find(i => i.type === 'feat' && ['sorcery points'].includes(i.name.toLowerCase().trim()));\n    const cost = Number(workflow.activity?.consumption?.targets?.[0]?.value ?? 0);\n    if (points && cost && (points.system.uses?.spent ?? 0) >= cost) {\n        await genericUtils.update(points, {'system.uses.spent': points.system.uses.spent - cost});\n    }\n    ui.notifications.info(title + ': ' + why + ' Sorcery Points refunded.');\n};\nconst castableSpells = () => {\n    const slots = Object.entries(actor.system.spells ?? {})\n        .filter(([key, slot]) => (slot?.value ?? 0) > 0)\n        .map(([key, slot]) => key === 'pact' ? Number(slot.level ?? 0) : Number(key.replace('spell', '')))\n        .filter(n => n > 0);\n    const maxSlot = Math.max(0, ...slots);\n    const seen = new Set();\n    return actor.items.filter(s => {\n        if (s.type !== 'spell') return false;\n        const lvl = s.system.level ?? 0;\n        const method = s.system.method ?? s.system.preparation?.mode;\n        const ok = lvl === 0 || ['atwill', 'innate'].includes(method)\n            || (s.system.uses?.max && (s.system.uses.value ?? 0) > 0 && method !== 'spell')\n            || maxSlot >= lvl;\n        if (!ok) return false;\n        const key = s.name + '|' + lvl;\n        if (seen.has(key)) return false;\n        seen.add(key);\n        return true;\n    });\n};\nconst actionActivity = s => (s.system.activities?.contents ?? []).find(a => a.activation?.type === 'action');\nconst spells = castableSpells().filter(s => actionActivity(s))\n    .sort((a, b) => (a.system.level - b.system.level) || a.name.localeCompare(b.name));\nif (!spells.length) return refundAndClear('no castable 1-action spells.');\nconst spell = await dialogUtils.selectDocumentDialog(title,\n    'Quicken which spell? (Spells that take 1 action. It will take your Bonus Action instead.)', spells,\n    {showSpellLevel: true, addNoneDocument: true});\nif (!spell) return refundAndClear('no spell chosen.');\nconst castWith = actionActivity(spell);\nsetTimeout(() => castWith?.use(), 250);\n",
 "incarnate": "// =====================================================================\n//  SORCERY INCARNATE (2024): Chris's Premades Embedded Macro\n//  Put on: the \"Sorcery Incarnate\" feature  (the installer does this for you)\n//  Type: Midi Actor   |   Pass: rollFinished   |   Priority: 20\n//\n//  While Innate Sorcery is active he can use two Metamagic options on one\n//  spell. When he clicks Heightened, Twinned or Quickened Spell, he's asked\n//  whether to add a second option to the same spell before he picks it.\n//  The second option spends its own Sorcery Points and is \"primed\" without\n//  casting anything; then the first option's spell list appears as usual and\n//  the one spell gets both.\n//  Seeking Spell isn't offered here: it already triggers on its own.\n// =====================================================================\n\nconst OPTIONS = {                 // option name -> primed effect identifier\n    'heightened spell': 'heightenedSpellPrimed',\n    'twinned spell': 'twinnedSpellPrimed',\n    'quickened spell': 'quickenedSpellPrimed'\n};\nconst WAIT_MS = 20000;\n\nconst actor = workflow.actor;\nconst baseName = i => i.name.toLowerCase().replace(/^metamagic\\s*[:\\-–]\\s*/, '').trim();\nconst first = workflow.item;\nif (first?.type !== 'feat' || !OPTIONS[baseName(first)]) return;\nif (actor.getFlag('world', 'nixMetamagicPrimeOnly')) return;      // this IS the second option\n\n// Innate Sorcery must be active.\nconst innate = actor.appliedEffects.find(e => /innate sorcery/i.test(e.name));\nif (!innate) return;\n\nconst points = actor.items.find(i => i.type === 'feat' && i.name.toLowerCase().trim() === 'sorcery points');\nconst left = points?.system.uses?.value ?? 0;\nconst costOf = i => Number(i.system.activities?.contents?.[0]?.consumption?.targets?.find(t => t.type === 'itemUses')?.value ?? 0);\nconst choices = actor.items.filter(i => i.type === 'feat' && OPTIONS[baseName(i)]\n    && baseName(i) !== baseName(first) && costOf(i) <= left\n    && !effectUtils.getEffectByIdentifier(actor, OPTIONS[baseName(i)]));\nif (!choices.length) return;\n\nconst userId = socketUtils.firstOwner(actor, true) ?? game.user.id;\nconst second = await dialogUtils.selectDocumentDialog(trigger.entity.name,\n    'Innate Sorcery is active. Add a second Metamagic option to this spell? (' + left + ' Sorcery Points left)',\n    choices, {addNoneDocument: true, userId});\nif (!second) return;\n\nconst activity = second.system.activities?.contents?.[0];\nif (!activity) return ui.notifications.warn('Sorcery Incarnate: ' + second.name + ' has no activity.');\nawait actor.setFlag('world', 'nixMetamagicPrimeOnly', true);\ntry {\n    await activity.use({}, {configure: false});\n    // Wait for the second option to prime itself.\n    const id = OPTIONS[baseName(second)];\n    const start = Date.now();\n    while (!effectUtils.getEffectByIdentifier(actor, id) && Date.now() - start < WAIT_MS) await genericUtils.sleep(250);\n} finally {\n    if (actor.getFlag('world', 'nixMetamagicPrimeOnly')) await actor.unsetFlag('world', 'nixMetamagicPrimeOnly');\n}\nawait ChatMessage.create({\n    speaker: ChatMessage.getSpeaker({actor}),\n    content: '<b>Sorcery Incarnate:</b> ' + actor.name + ' weaves ' + first.name + ' and ' + second.name + ' into one spell.'\n});\n",
 "restoration": "// =====================================================================\n//  SORCEROUS RESTORATION: Chris's Premades Embedded Macro\n//  Put on: the \"Sorcerous Restoration\" feature  (the installer does this)\n//  Type: Rest   |   Pass: short   |   Priority: 50\n//\n//  When he finishes a Short Rest and Sorcerous Restoration has a use left\n//  (and he's missing Sorcery Points), he's asked whether to use it. Yes uses\n//  the feature exactly as if he'd clicked it.\n// =====================================================================\n\nif (trigger.data?.longRest) return;                 // long rests refill points anyway\nconst item = trigger.entity;\nif (item.system.uses?.max && !(item.system.uses.value > 0)) return;\nconst points = actor.items.find(i => i.type === 'feat' && i.name.toLowerCase().trim() === 'sorcery points');\nif (points && (points.system.uses?.spent ?? 0) <= 0) return;   // already full\nconst activity = item.system.activities?.contents?.[0];\nif (!activity) return;\nconst userId = socketUtils.firstOwner(actor, true) ?? game.user.id;\nconst regain = Math.floor((actor.classes?.sorcerer?.system.levels ?? 0) / 2);\nconst yes = await dialogUtils.confirm(item.name,\n    'Short rest finished. Use ' + item.name + ' to regain up to ' + (regain || 'some') + ' Sorcery Points? ('\n    + (points?.system.uses?.value ?? '?') + '/' + (points?.system.uses?.max ?? '?') + ' now)', {userId});\nif (!yes) return;\nawait activity.use({}, {configure: false});\n",
 "mantle": "// =====================================================================\n//  MANTLE OF FLAME (Phoenix Sorcery), folded into Innate Sorcery\n//  Put on: the \"Mantle of Flame / Innate Sorcery\" feature (installer does this)\n//  Type: Midi Item   |   Pass: rollFinished   |   Priority: 60\n//\n//  When he activates Innate Sorcery, Mantle of Flame starts with it and ends\n//  when Innate Sorcery ends (or when Phoenix Spark consumes it):\n//   - Bright light 30 ft, dim light 30 ft beyond.\n//   - A creature that hits him with a melee attack from within 5 ft takes fire\n//     damage equal to his Charisma modifier. (Touching him: apply by hand.)\n//   - On his turn, any damage roll of his that deals fire damage gets +Cha.\n//   - A fire aura plays on his token while it lasts.\n// =====================================================================\n\nconst MANTLE_IDENTIFIER = 'mantleOfFlame';\nconst actor = workflow.actor;\nconst item = workflow.item;\n\n// Find the Innate Sorcery effect this use just created (give it a moment).\nlet innate;\nfor (let i = 0; i < 10 && !innate; i++) {\n    innate = actor.effects.find(e => /innate sorcery/i.test(e.name) && !e.disabled);\n    if (!innate) await genericUtils.sleep(200);\n}\nif (!innate) return ui.notifications.warn('Mantle of Flame: no active Innate Sorcery effect found, so the Mantle did not start.');\n\n// ---- Scripts carried by the Mantle effect --------------------------------------\n// Hit back: runs for the target (him) when a melee attack hits him.\nconst onHit = async () => {\n    const mantle = trigger.entity;\n    const me = mantle.parent;\n    const myToken = actorUtils.getFirstToken(me);\n    if (!myToken || !workflow.token || workflow.actor?.uuid === me.uuid) return;\n    if (!Array.from(workflow.hitTargets ?? []).some(t => t.actor?.uuid === me.uuid)) return;\n    if (!workflowUtils.isAttackType(workflow, 'meleeAttack')) return;\n    if (tokenUtils.getDistance(workflow.token, myToken) > 5) return;\n    const cha = me.system.abilities.cha.mod;\n    if (cha <= 0) return;\n    const roll = await new CONFIG.Dice.DamageRoll(String(cha), {}, {type: 'fire'}).evaluate();\n    await workflowUtils.applyWorkflowDamage(myToken, roll, 'fire', [workflow.token],\n        {flavor: 'Mantle of Flame', sourceItem: {name: 'Mantle of Flame', img: mantle.img, type: 'feat'}});\n};\n// +Cha to his fire damage rolls on his turn.\nconst onDamage = async () => {\n    const mantle = trigger.entity;\n    const me = mantle.parent;\n    if (workflow.actor?.uuid !== me.uuid) return;\n    const c = game.combat;\n    if (c?.started && c.combatant?.actor?.uuid !== me.uuid) return;     // not his turn\n    if (!workflowUtils.getDamageTypes(workflow.damageRolls ?? []).has('fire')) return;\n    const cha = me.system.abilities.cha.mod;\n    if (cha <= 0) return;\n    await workflowUtils.bonusDamage(workflow, String(cha), {ignoreCrit: true, damageType: 'fire'});\n};\nconst animStart = async () => {\n    const mantle = trigger.entity;\n    const token = actorUtils.getFirstToken(mantle.parent);\n    if (!token || !globalThis.Sequencer) return;\n    const pick = list => list.find(f => Sequencer.Database.entryExists(f));\n    const below = pick(['jb2a.shield_themed.below.fire.03.orange', 'jb2a.shield_themed.below.fire.01.orange']);\n    const above = pick(['jb2a.shield_themed.above.fire.03.orange', 'jb2a.shield_themed.above.fire.01.orange']);\n    const NAME = 'Mantle of Flame ' + mantle.parent.id;\n    const seq = new Sequence();\n    if (below) seq.effect().file(below).attachTo(token).belowTokens().scaleToObject(1.8).fadeIn(500).fadeOut(400).persist().name(NAME);\n    if (above) seq.effect().file(above).attachTo(token).scaleToObject(1.8).opacity(0.5).fadeIn(900).fadeOut(400).persist().name(NAME);\n    await seq.play();\n};\nconst animEnd = async () => {\n    if (!globalThis.Sequencer) return;\n    const mantle = trigger.entity;\n    await Sequencer.EffectManager.endEffects({name: 'Mantle of Flame ' + mantle.parent.id});\n};\n// Ends the Mantle when Innate Sorcery ends (carried by the Innate Sorcery effect).\nconst endWithInnate = async () => {\n    const me = trigger.entity.parent;\n    const mantle = effectUtils.getEffectByIdentifier(me, 'mantleOfFlame');\n    if (mantle) await genericUtils.remove(mantle);\n};\nconst run = fn => 'await (' + fn.toString() + ')();';\n\nconst old = effectUtils.getEffectByIdentifier(actor, MANTLE_IDENTIFIER);\nif (old) await genericUtils.remove(old);\nconst dur = innate.duration?.seconds ? {seconds: innate.duration.seconds} : {seconds: 60};\nawait effectUtils.createEffect(actor, {\n    name: 'Mantle of Flame',\n    img: 'icons/magic/fire/flame-burning-creature-skeleton.webp',\n    origin: item.uuid,\n    duration: dur,\n    description: 'Bright light 30 ft, dim 30 ft more. Melee attackers within 5 ft take fire damage equal to his Charisma modifier. On his turn his fire damage rolls gain +Charisma modifier.',\n    changes: [\n        {key: 'ATL.light.bright', mode: CONST.ACTIVE_EFFECT_MODES.UPGRADE, value: '30', priority: 20},\n        {key: 'ATL.light.dim', mode: CONST.ACTIVE_EFFECT_MODES.UPGRADE, value: '60', priority: 20}\n    ],\n    flags: {'chris-premades': {embeddedMacros: [\n        {name: 'Mantle of Flame hit back', type: 'midi-actor', pass: 'onHit', priority: 250, macro: run(onHit)},\n        {name: 'Mantle of Flame fire bonus', type: 'midi-actor', pass: 'damageRollComplete', priority: 60, macro: run(onDamage)},\n        {name: 'Mantle of Flame anim start', type: 'effect', pass: 'created', priority: 50, macro: run(animStart)},\n        {name: 'Mantle of Flame anim end', type: 'effect', pass: 'deleted', priority: 50, macro: run(animEnd)}\n    ]}}\n}, {identifier: MANTLE_IDENTIFIER});\n\n// Tie it to Innate Sorcery.\nconst innateMacros = (innate.flags?.['chris-premades']?.embeddedMacros ?? []).filter(m => m.name !== 'End Mantle of Flame');\ninnateMacros.push({name: 'End Mantle of Flame', type: 'effect', pass: 'deleted', priority: 50, macro: run(endWithInnate)});\nawait innate.setFlag('chris-premades', 'embeddedMacros', innateMacros);\n\nawait ChatMessage.create({\n    speaker: ChatMessage.getSpeaker({actor}),\n    content: '<b>Mantle of Flame:</b> phoenix fire wreathes ' + actor.name + ', eyes glowing like hot coals.'\n});\n",
 "sparkUse": "await (async () => {\n    const me = workflow.actor;\n    const item = workflow.item;\n    const mantle = effectUtils.getEffectByIdentifier(me, 'mantleOfFlame');\n    const level = me.classes?.sorcerer?.system.levels ?? 0;\n    const cha = me.system.abilities.cha.mod;\n    const dmg = mantle ? level + 2 * cha : Math.floor(level / 2) + cha;\n    await me.setFlag('world', 'nixPhoenixSparkAt', Date.now());\n\n    const myToken = workflow.token ?? actorUtils.getFirstToken(me);\n    if (myToken && globalThis.Sequencer) {\n        const f = ['jb2a.fireball.explosion.orange', 'jb2a.explosion.01.orange', 'jb2a.explosion.orange.0']\n            .find(x => Sequencer.Database.entryExists(x));\n        if (f) new Sequence().effect().file(f).atLocation(myToken).size(5, {gridUnits: true}).play();\n    }\n    if (myToken && dmg > 0) {\n        const victims = canvas.tokens.placeables.filter(t => t.actor && t.id !== myToken.id\n            && !t.document.hidden && tokenUtils.getDistance(myToken, t) <= 10);\n        if (victims.length) {\n            const roll = await new CONFIG.Dice.DamageRoll(String(dmg), {}, {type: 'fire'}).evaluate();\n            await workflowUtils.applyWorkflowDamage(myToken, roll, 'fire', victims, {flavor: item.name, sourceItem: item});\n        }\n    }\n    if (mantle) await genericUtils.remove(mantle);\n    // Already at 0? Bring him back to 1 (covers the order where the damage landed first).\n    const fixHp = async () => { if ((me.system.attributes.hp.value ?? 1) <= 0) await me.update({'system.attributes.hp.value': 1}); };\n    await fixHp();\n    setTimeout(fixHp, 1500);\n    await ChatMessage.create({\n        speaker: ChatMessage.getSpeaker({actor: me}),\n        content: '<b>' + item.name + ':</b> ' + me.name + ' refuses to fall! The phoenix fire roars outward ('\n            + dmg + ' fire damage within 10 ft)' + (mantle ? ' and the Mantle of Flame burns out.' : '.')\n    });\n})();",
 "sparkGuard": "await (async () => {\n    const item = trigger.entity;\n    const me = item.actor;\n    if (!ditem || ditem.newHP > 0 || ditem.oldHP <= 0) return;\n    // Clicked by hand a moment ago: the burst already happened, just keep him at 1 HP.\n    const at = me.getFlag('world', 'nixPhoenixSparkAt') ?? 0;\n    if (Date.now() - at < 15000) { workflowUtils.preventDeath(ditem); return; }\n    if (item.system.uses?.max && !(item.system.uses.value > 0)) return;\n    const inCombat = combatUtils.inCombat();\n    if (inCombat && actorUtils.hasUsedReaction(me)) return;\n\n    const mantle = effectUtils.getEffectByIdentifier(me, 'mantleOfFlame');\n    const level = me.classes?.sorcerer?.system.levels ?? 0;\n    const cha = me.system.abilities.cha.mod;\n    const dmg = mantle ? level + 2 * cha : Math.floor(level / 2) + cha;\n    const userId = socketUtils.firstOwner(me, true) ?? game.user.id;\n    const yes = await dialogUtils.confirm(item.name,\n        'You are about to drop to 0 HP. Use your reaction for ' + item.name + '? You drop to 1 HP instead and everything within 10 ft takes '\n        + dmg + ' fire damage' + (mantle ? ' (Mantle of Flame boosts it, then ends)' : '') + '.', {userId});\n    if (!yes) return;\n\n    workflowUtils.preventDeath(ditem);\n    await me.setFlag('world', 'nixPhoenixSparkAt', Date.now());\n    if (item.system.uses?.max) await genericUtils.update(item, {'system.uses.spent': (item.system.uses.spent ?? 0) + 1});\n    if (inCombat) await actorUtils.setReactionUsed(me);\n\n    const myToken = actorUtils.getFirstToken(me);\n    const blast = async () => {\n        if (myToken && globalThis.Sequencer) {\n            const f = ['jb2a.fireball.explosion.orange', 'jb2a.explosion.01.orange', 'jb2a.explosion.orange.0']\n                .find(x => Sequencer.Database.entryExists(x));\n            if (f) new Sequence().effect().file(f).atLocation(myToken).size(5, {gridUnits: true}).play();\n        }\n        if (myToken && dmg > 0) {\n            const victims = canvas.tokens.placeables.filter(t => t.actor && t.id !== myToken.id\n                && !t.document.hidden && tokenUtils.getDistance(myToken, t) <= 10);\n            if (victims.length) {\n                const roll = await new CONFIG.Dice.DamageRoll(String(dmg), {}, {type: 'fire'}).evaluate();\n                await workflowUtils.applyWorkflowDamage(myToken, roll, 'fire', victims, {flavor: item.name, sourceItem: item});\n            }\n        }\n        const m = effectUtils.getEffectByIdentifier(me, 'mantleOfFlame');\n        if (mantle && m) await genericUtils.remove(m);\n        await ChatMessage.create({\n            speaker: ChatMessage.getSpeaker({actor: me}),\n            content: '<b>' + item.name + ':</b> ' + me.name + ' refuses to fall! The phoenix fire roars outward ('\n                + dmg + ' fire damage within 10 ft)' + (mantle ? ' and the Mantle of Flame burns out.' : '.')\n        });\n    };\n    setTimeout(blast, 300);   // let the damage that triggered it land first\n})();"
};
const actor = canvas.tokens.controlled[0]?.actor ?? game.user.character;
if (!actor) return ui.notifications.warn('Bangiras fixes: select Bangiras\'s token first.');
const report = [];
const baseName = i => i.name.toLowerCase().replace(/^metamagic\s*[:\-–]\s*/, '').trim();
const findItem = (names, type) => actor.items.find(i => (!type || i.type === type) && names.includes(baseName(i)));
 
// Replace embedded macros on a document (Item or ActiveEffect). `drop` decides which old ones go.
async function setMacros(doc, drop, add) {
    const current = doc.flags?.['chris-premades']?.embeddedMacros ?? [];
    const kept = current.filter(m => !drop(m));
    await doc.setFlag('chris-premades', 'embeddedMacros', kept.concat(add));
    return current.length - kept.length;
}
// Replace a macro wherever it lives on an item (item level or any activity), matched by its code.
async function replaceByCode(item, marker, script, defaults) {
    let replaced = 0;
    const itemMacros = item.flags?.['chris-premades']?.embeddedMacros ?? [];
    if (itemMacros.some(m => String(m.macro).includes(marker))) {
        await item.setFlag('chris-premades', 'embeddedMacros',
            itemMacros.map(m => String(m.macro).includes(marker) ? {...m, macro: script} : m));
        replaced++;
    }
    const actMacros = item.flags?.['chris-premades']?.embeddedActivityMacros ?? {};
    for (const [id, list] of Object.entries(actMacros)) {
        if (!(list ?? []).some(m => String(m.macro).includes(marker))) continue;
        await item.setFlag('chris-premades', 'embeddedActivityMacros.' + id,
            list.map(m => String(m.macro).includes(marker) ? {...m, macro: script} : m));
        replaced++;
    }
    if (!replaced && defaults) {
        await item.setFlag('chris-premades', 'embeddedMacros', itemMacros.concat([{...defaults, macro: script}]));
        return 'added';
    }
    return replaced ? 'updated' : 'missing';
}
const cprAuto = item => item?.flags?.['chris-premades']?.info?.identifier;
 
// ---- 1. Magicians Judge ----------------------------------------------------------
const staff = actor.items.find(i => i.name.toLowerCase().trim() === 'magicians judge');
if (!staff) report.push('<li><b>Magicians Judge</b> not found: skipped Stasis and Sand Shroud.</li>');
else {
    await setMacros(staff, m => m.name === 'Magicians Judge: Stasis', [
        {name: 'Magicians Judge: Stasis', type: 'save', pass: 'situational', priority: 50, macro: SCRIPTS.stasis}]);
    report.push('<li>Stasis v2 installed (advantage vs Topple and anything that knocks prone).</li>');
    const shroud = staff.effects.find(e => e.name === 'Sand Shroud');
    if (!shroud) report.push('<li><b>Sand Shroud</b> effect not found on the staff: run the Magicians Judge setup first.</li>');
    else {
        await setMacros(shroud, m => /^Sand Shroud anim/.test(m.name), [
            {name: 'Sand Shroud anim start', type: 'effect', pass: 'created', priority: 50, macro: SCRIPTS.sandStart},
            {name: 'Sand Shroud anim end', type: 'effect', pass: 'deleted', priority: 50, macro: SCRIPTS.sandEnd}]);
        report.push('<li>Sand Shroud animation installed.</li>');
    }
}
 
// ---- 2. Metamagic ------------------------------------------------------------------
const points = actor.items.find(i => i.type === 'feat' && i.name.toLowerCase().trim() === 'sorcery points');
const heightened = findItem(['heightened spell'], 'feat');
const twinned = findItem(['twinned spell'], 'feat');
const quickened = findItem(['quickened spell'], 'feat');
const mm = {name: 'Metamagic', type: 'midi-item', pass: 'rollFinished', priority: 50};
if (heightened) report.push('<li>Heightened Spell: ' + await replaceByCode(heightened, 'heightenedSpellPrimed', SCRIPTS.heightened, {...mm, name: 'Heightened Spell'}) + '.</li>');
if (twinned) report.push('<li>Twinned Spell: ' + await replaceByCode(twinned, 'twinnedSpellPrimed', SCRIPTS.twinned, {...mm, name: 'Twinned Spell'}) + '.</li>');
if (!quickened) report.push('<li><b>Quickened Spell</b> not found.</li>');
else {
    await replaceByCode(quickened, 'quickenedSpellPrimed', SCRIPTS.quickened, {...mm, name: 'Quickened Spell'});
    const act = quickened.system.activities?.contents?.[0];
    if (!act) report.push('<li><b>Quickened Spell</b> has no activity: add a Utility activity and run again.</li>');
    else if (points && !(act.consumption?.targets ?? []).some(t => t.type === 'itemUses')) {
        await act.update({'consumption.targets': [{type: 'itemUses', target: points.id, value: '2', scaling: {}}]});
    }
    report.push('<li>Quickened Spell installed (2 Sorcery Points).' + (cprAuto(quickened) ? ' <b>It still has a CPR automation: set it to None in the Medkit.</b>' : '') + '</li>');
}
 
// ---- 3. Sorcery Incarnate ------------------------------------------------------------
const incarnate = actor.items.find(i => i.name.toLowerCase().trim() === 'sorcery incarnate');
if (!incarnate) report.push('<li><b>Sorcery Incarnate</b> not found.</li>');
else {
    await setMacros(incarnate, m => m.name === 'Sorcery Incarnate' || String(m.macro).includes('nixMetamagicPrimeOnly'), [
        {name: 'Sorcery Incarnate', type: 'midi-actor', pass: 'rollFinished', priority: 20, macro: SCRIPTS.incarnate}]);
    report.push('<li>Sorcery Incarnate installed.</li>');
}
 
// ---- 4. Sorcerous Restoration --------------------------------------------------------
const restoration = actor.items.find(i => i.name.toLowerCase().trim() === 'sorcerous restoration');
if (!restoration) report.push('<li><b>Sorcerous Restoration</b> not found.</li>');
else {
    await setMacros(restoration, m => m.name === 'Sorcerous Restoration prompt', [
        {name: 'Sorcerous Restoration prompt', type: 'rest', pass: 'short', priority: 50, macro: SCRIPTS.restoration}]);
    report.push('<li>Sorcerous Restoration will ask after a Short Rest.</li>');
}
 
// ---- 5. Fire Shield check -------------------------------------------------------------
const fireShield = actor.items.find(i => i.type === 'spell' && i.name.toLowerCase().trim() === 'fire shield');
if (fireShield) report.push(cprAuto(fireShield) === 'fireShield'
    ? '<li>Fire Shield already uses CPR\'s automation.</li>'
    : '<li><b>Fire Shield</b> isn\'t using CPR\'s automation. Open its Medkit and apply the Chris\'s Premades version: it hits the attacker automatically.</li>');
 
// ---- 6. Mantle of Flame (inside Innate Sorcery) + Phoenix Spark ---------------------
const mantleItem = actor.items.find(i => /mantle of flame/i.test(i.name)) ?? actor.items.find(i => /^innate sorcery$/i.test(i.name.trim()));
if (!mantleItem) report.push('<li><b>Mantle of Flame / Innate Sorcery</b> not found.</li>');
else {
    await setMacros(mantleItem, m => m.name === 'Mantle of Flame start', [
        {name: 'Mantle of Flame start', type: 'midi-item', pass: 'rollFinished', priority: 60, macro: SCRIPTS.mantle}]);
    report.push('<li>Mantle of Flame now starts and ends with Innate Sorcery (' + mantleItem.name + ').</li>');
}
const spark = actor.items.find(i => i.name.toLowerCase().trim() === 'phoenix spark');
if (!spark) report.push('<li><b>Phoenix Spark</b> not found.</li>');
else {
    await setMacros(spark, m => /^Phoenix Spark (trigger|use|guard)$/.test(m.name), [
        {name: 'Phoenix Spark use', type: 'midi-item', pass: 'rollFinished', priority: 50, macro: SCRIPTS.sparkUse},
        {name: 'Phoenix Spark guard', type: 'midi-actor', pass: 'targetApplyDamage', priority: 245, macro: SCRIPTS.sparkGuard}]);
    report.push('<li>Phoenix Spark: our prompt appears when he would drop to 0 HP (1 HP + fire burst).'
        + (spark.flags?.['chris-premades']?.info?.identifier ? ' <b>It still has a Chris\'s Premades automation: set it to None so only one prompt shows.</b>' : '') + '</li>');
}
// ---- 7. Hold Monster / Hold Person end-of-turn saves ---------------------------------
for (const spell of actor.items.filter(i => i.type === 'spell' && ['hold monster', 'hold person'].includes(i.name.toLowerCase().trim()))) {
    const act = (spell.system.activities?.contents ?? []).find(a => a.type === 'save') ?? spell.system.activities?.contents?.[0];
    const dc = Number(act?.save?.dc?.value) || Number(actor.system.attributes?.spell?.dc) || 13;
    const effects = spell.effects.filter(e => e.statuses?.has?.('paralyzed') || /paralyz|hold/i.test(e.name));
    if (!effects.length) { report.push('<li><b>' + spell.name + '</b> has no Paralyzed effect to patch.</li>'); continue; }
    for (const effect of effects) {
        const changes = (effect.changes ?? []).filter(c => c.key !== 'flags.midi-qol.OverTime');
        changes.push({key: 'flags.midi-qol.OverTime', mode: CONST.ACTIVE_EFFECT_MODES.OVERRIDE, priority: 20,
            value: 'turn=end, saveAbility=wis, saveDC=' + dc + ', label=' + spell.name + ' (end of turn save)'});
        await effect.update({changes});
    }
    await setMacros(spell, m => m.name === 'Hold spell live DC', [
        {name: 'Hold spell live DC', type: 'midi-item', pass: 'rollFinished', priority: 60, macro: SCRIPTS.holdDc}]);
    report.push('<li>' + spell.name + ': end-of-turn Wisdom save, using the DC of each cast (Innate Sorcery etc. included).</li>');
}
 
// ---- 8. Clean up leftover Heightened effects anywhere in the world -------------------
{
    const all = new Set(game.actors.contents);
    for (const sc of game.scenes) for (const t of sc.tokens) if (!t.actorLink && t.actor) all.add(t.actor);
    let removed = 0;
    for (const a of all) {
        for (const e of a.effects.filter(e => e.flags?.world?.heightenedTarget)) {
            const su = e.flags.world.heightenedTarget.spellUuid;
            const lingering = a.effects.some(x => x.id !== e.id && (x.origin === su || String(x.origin ?? '').startsWith(su + '.')));
            if (!lingering) { await e.delete(); removed++; }
        }
    }
    report.push('<li>Heightened Spell now ends once the spell stops affecting the target. Removed ' + removed + ' leftover Heightened effect' + (removed === 1 ? '' : 's') + '.</li>');
}
 
await ChatMessage.create({whisper: [game.user.id], content: '<b>Bangiras fixes on ' + actor.name + '</b><ul>' + report.join('') + '</ul>'});
 